<div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header"><strong>Visitas registradas</strong></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Visitante</th><th>Destino</th><th>Entrada / salida</th><th>Estado</th></tr></thead><tbody><?php foreach($vis as $v):?><tr><td><strong><?=e($v['visitor_name'])?></strong><small class="d-block text-body-secondary">Atiende: <?=e($v['host']?:'No indicado')?></small></td><td><?=e($v['unit'])?></td><td><?=e($v['check_in_at']?format_datetime_es((string)$v['check_in_at']):'Esperado')?><?php if($v['check_out_at']):?><small class="d-block">Salida: <?=e(format_datetime_es((string)$v['check_out_at']))?></small><?php endif;?></td><td><span class="badge text-bg-<?=e(status_badge((string)$v['status']))?>"><?=e(status_label((string)$v['status']))?></span></td></tr><?php endforeach;?><?php if(!$vis):?><tr><td colspan="4" class="text-center text-body-secondary py-4">No hay visitas registradas.</td></tr><?php endif;?></tbody></table></div></div></div></div><div class="col-xl-5"><div class="card"><div class="card-header"><strong>Invitaciones desde Property App</strong></div><div class="card-body"><?php foreach($inv as $i):?><div class="approval-item"><div><strong><?=e($i['visitor_name'])?></strong><span><?=e(format_datetime_es((string)$i['starts_at']))?>–<?=e(date('H:i',strtotime((string)$i['ends_at'])))?></span><small><?=e($i['unit'])?> · Código <?=e($i['access_code'])?> · Host: <?=e($i['host'])?></small></div><span class="badge text-bg-info"><?=e(status_label((string)$i['status']))?></span></div><?php endforeach;?><?php if(!$inv):?><div class="text-center text-body-secondary py-4">No hay invitaciones creadas.</div><?php endif;?></div></div></div></div>
